SELECT CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, MIN(t.txn_time) AS first_txn_time, ROUND(STDDEV(t.amount), 2) AS stddev_amount FROM transactions t FULL OUTER JOIN accounts a ON t.account_id = a.id RIGHT JOIN customers c ON a.customer_id = c.id GROUP BY CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_FORMAT(c.signup_date, 'yyyy-MM') ORDER BY 1, signup_month LIMIT 50
